	@Override
	public void setupAnim(State state) {
		super.setupAnim(state);
		head.yRot += state.yRot * 0.017453292F * 1.0F;
		head.xRot += state.xRot * 0.017453292F * 1.0F;
		arm_l.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.9F * state.walkAnimationSpeed;
		arm_l.zRot += Mth.sin(state.ageInTicks * 0.09F + 0.0F) * (0.03F + 0.0F * state.walkAnimationSpeed);
		arm_r.zRot += Mth.sin(state.ageInTicks * 0.09F + 3.141592653589793F) * (0.03F + 0.0F * state.walkAnimationSpeed);
		beard.xRot += Mth.sin(state.ageInTicks * 0.12F + 0.0F) * (0.08F + 0.0F * state.walkAnimationSpeed);
		beard2.xRot += Mth.sin(state.ageInTicks * 0.15F + 1.0F) * (0.1F + 0.0F * state.walkAnimationSpeed);
		ear_l.zRot += Mth.sin(state.ageInTicks * 0.17F + 0.0F) * (0.1F + 0.0F * state.walkAnimationSpeed);
		ear_r.zRot += Mth.sin(state.ageInTicks * 0.17F + 1.6F) * (0.1F + 0.0F * state.walkAnimationSpeed);
		gleg_l.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 1.0F * state.walkAnimationSpeed;
		gleg_r.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 1.0F * state.walkAnimationSpeed;
		tail.xRot += Mth.sin(state.ageInTicks * 0.21F + 0.0F) * (0.18F + 0.3F * state.walkAnimationSpeed);
	}
